mapper.sql:
SELECT SN.ID, SN.CREATOR, SN.CREATE_TIME, SN.MODIFIER, SN.MODIFY_TIME, SN.LOGIC_DEL, SN.REC_VER, SN.BUILD_IN, SN.TENANT_ID, SN.TITLE, SN.TYPE, SN.EFFECTIVE_TIME_FROM, SN.EFFECTIVE_TIME_TO, SN.CONTENT, SN.PUBLISHER_ID, SN.REMARK, SU.NICK_NAME AS PUBLISHER_NAME, SN.USER_ID, SN.CATEGORY, SN.READ_FLAG, SN.EXCERPT, SN.ANNOUNCEMENT_ID FROM sys_notice sn LEFT JOIN sys_user su on su.id = sn.PUBLISHER_ID WHERE 1 = 1 AND SN.LOGIC_DEL = 0
AND SN.USER_ID = #{sysNoticeDto.userId}
AND SN.ID = #{sysNoticeDto.id}
AND SN.TYPE = #{sysNoticeDto.type}
AND SN.CREATE_TIME BETWEEN #{sysNoticeDto.createTimeFrom} AND #{sysNoticeDto.createTimeTo}
order by SN.ID desc

